#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.AI;using UnityEditor;using UnityEditor.SceneManagement;using Unity.AI.Navigation;
namespace DeliveryService.Mok.Editor {
public static class VenueEscapeUpgrade {
 const string Env="Assets/Synty/PolygonHeist/Prefab/Environment/";
 static VenueFinale Find(){var m=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();if(!m){EditorSceneManager.OpenScene(StoryTutorialBuilder.Main,OpenSceneMode.Additive);m=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();}return m;}
 static Bounds BoundsOf(GameObject g){var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
 static Transform Point(string name,Transform root,Vector3 world){var t=new GameObject(name).transform;t.SetParent(root,false);t.position=world;return t;}
 static GameObject Fit(string path,Transform root,Vector3 center,Vector3 size,float yaw=0){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path));g.transform.SetParent(root,false);g.transform.rotation=Quaternion.Euler(0,yaw,0);var b=BoundsOf(g);var f=new Vector3(size.x/Mathf.Max(.001f,b.size.x),b.size.y<.001f?1:size.y/b.size.y,size.z/Mathf.Max(.001f,b.size.z));bool swap=Mathf.Abs(Mathf.Sin(yaw*Mathf.Deg2Rad))>.5f;g.transform.localScale=Vector3.Scale(g.transform.localScale,swap?new Vector3(f.z,f.y,f.x):f);b=BoundsOf(g);g.transform.position+=center-b.center;foreach(var c in g.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);return g;}
 public static void Apply(){var m=Find();if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var scene=m.gameObject.scene;if(!EditorSceneManager.SaveScene(scene,"Logs/Venue-before-return-entry-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true))throw new Exception("Backup failed");if(m.streetPursuit)throw new Exception("Already installed");var w=m.interior.transform;
 var root=new GameObject("Synty venue architectural finish").transform;root.SetParent(w,false);
 var cream=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/VenueFinale/Venue plaster.mat");
 GameObject Solid(string name,Vector3 p,Vector3 size){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(w,false);g.transform.localPosition=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=cream;return g;}
 // 열린 비상문 옆에는 문 폭에 맞춘 양쪽 벽체가 필요하다.
 Solid("Emergency door solid left jamb",new Vector3(-6,1.4f,-24.5f),new Vector3(.24f,2.8f,1));Solid("Emergency door solid right jamb",new Vector3(-6,1.4f,-27.5f),new Vector3(.24f,2.8f,1));
 // 홀 벽 위의 가는 틈도 천장까지 막는다.
 foreach(var r in w.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name=="Side wall"||r.name=="End wall"||r.name=="Rear wall left"||r.name=="Rear wall right").ToArray()){var b=r.bounds;Solid("Ceiling closure "+r.name,w.InverseTransformPoint(new Vector3(b.center.x,w.position.y+4.25f,b.center.z)),new Vector3(b.size.x,.3f,b.size.z));}
 var walls=w.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.enabled&&r.GetComponent<BoxCollider>()&&r.bounds.size.y>2.5f&&Mathf.Min(r.bounds.size.x,r.bounds.size.z)<.5f&&Mathf.Max(r.bounds.size.x,r.bounds.size.z)>1&& !r.name.Contains("door",StringComparison.OrdinalIgnoreCase)&&!r.name.Contains("Backdrop")).ToArray();
 foreach(var r in walls){var b=r.bounds;bool alongX=b.size.x>b.size.z;float length=alongX?b.size.x:b.size.z;int pieces=Mathf.CeilToInt(length/5);float step=length/pieces;for(int n=0;n<pieces;n++)foreach(int side in new[]{-1,1}){Vector3 at=b.center+(alongX?Vector3.right:Vector3.forward)*(-length*.5f+(n+.5f)*step)+(alongX?Vector3.forward:Vector3.right)*((alongX?b.size.z:b.size.x)*.5f+.015f)*side;Fit(Env+"SM_Env_Wall_Interior_01.prefab",root,at,alongX?new Vector3(step,b.size.y,.075f):new Vector3(.075f,b.size.y,step),alongX?(side<0?0:180):(side<0?90:270));}r.enabled=false;EditorUtility.SetDirty(r);}
 foreach(var r in w.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name=="Interior floor"||r.name=="Reception wing floor"||r.name=="Service corridor floor"||r.name=="Dogleg corridor floor").ToArray()){var b=r.bounds;int nx=Mathf.CeilToInt(b.size.x/5),nz=Mathf.CeilToInt(b.size.z/5);float dx=b.size.x/nx,dz=b.size.z/nz;for(int x=0;x<nx;x++)for(int z=0;z<nz;z++)Fit(Env+(r.name=="Interior floor"?"SM_Env_Floor_02.prefab":"SM_Env_Floor_01.prefab"),root,new Vector3(b.min.x+(x+.5f)*dx,b.max.y+.003f,b.min.z+(z+.5f)*dz),new Vector3(dx,0,dz));}
 // 원래 입장했던 접수실로 돌아와 같은 도시 출입구로 나간다.
 m.interiorExit.position=w.TransformPoint(new Vector3(-28,.04f,-12));m.interiorExit.rotation=Quaternion.Euler(0,180,0);m.interiorExit.name="Original reception exit";
 var routes=new GameObject("Return to reception route").transform;routes.SetParent(w,false);
 m.serviceRoute=new[]{new Vector3(-7,.04f,4),new Vector3(-13,.04f,4.5f),new Vector3(-18,.04f,-4),new Vector3(-30,.04f,-4.5f),new Vector3(-30,.04f,-10)}.Select((p,n)=>Point("Reception return "+n,routes,w.TransformPoint(p))).Concat(new[]{m.interiorExit}).ToArray();
 Fit(Env+"SM_Env_Door_01.prefab",root,w.TransformPoint(new Vector3(-28,1.35f,-13.7f)),new Vector3(1.8f,2.7f,.12f));
 m.streetArrival.position=m.entry.position;
 var streetPath=new NavMeshPath();if(!NavMesh.CalculatePath(m.entry.position,m.carStand.position,NavMesh.AllAreas,streetPath)||streetPath.status!=NavMeshPathStatus.PathComplete)throw new Exception("No street route");
 var streetRoot=new GameObject("Venue pursuit street route").transform;streetRoot.SetParent(m.transform);m.alleyRoute=streetPath.corners.Skip(1).Take(streetPath.corners.Length-2).Select((at,n)=>Point("Vehicle route "+n,streetRoot,at)).ToArray();m.escapeTurn=m.alleyRoute.Last();m.streetArrival.rotation=Quaternion.LookRotation(m.alleyRoute[0].position-m.entry.position);
 var chase=m.gameObject.AddComponent<VenueStreetPursuit>();m.streetPursuit=chase;chase.mission=m;
 float total=0;for(int n=1;n<streetPath.corners.Length;n++)total+=Vector3.Distance(streetPath.corners[n-1],streetPath.corners[n]);
 Vector3 Along(float fraction){float d=total*fraction;for(int n=1;n<streetPath.corners.Length;n++){float len=Vector3.Distance(streetPath.corners[n-1],streetPath.corners[n]);if(d<=len)return Vector3.Lerp(streetPath.corners[n-1],streetPath.corners[n],d/len);d-=len;}return m.carStand.position;}
 chase.secondTrigger=Point("Street reinforcement trigger",streetRoot,Along(.32f));chase.thirdTrigger=Point("Last interception trigger",streetRoot,Along(.68f));
 Transform[] Posts(Vector3 center,int wave){var result=new System.Collections.Generic.List<Transform>();for(int n=0;n<4;n++){bool found=false;for(int trial=0;trial<24&&!found;trial++){Vector3 pos=center+Quaternion.Euler(0,trial*45+n*70,0)*Vector3.forward*(5+(trial/8)*3);if(!NavMesh.SamplePosition(pos,out var hit,2,NavMesh.AllAreas))continue;if(Vector3.Distance(hit.position,m.entry.position)<6||result.Any(t=>Vector3.Distance(t.position,hit.position)<1.8f))continue;var path=new NavMeshPath();if(!NavMesh.CalculatePath(hit.position,m.carStand.position,NavMesh.AllAreas,path)||path.status!=NavMeshPathStatus.PathComplete)continue;var node=Point("Street wave "+wave+" guard "+n,streetRoot,hit.position);node.rotation=Quaternion.LookRotation(m.entry.position-hit.position);result.Add(node);found=true;}if(!found)throw new Exception("No pursuit post "+wave+"/"+n);}return result.ToArray();}
 chase.firstWave=Posts(Along(.07f),1);chase.secondWave=Posts(Along(.43f),2);chase.thirdWave=Posts(Along(.8f),3);
 // 프롤로그와 본게임의 동일한 후드 플레이어 스킨을 기존 탑승 뼈대에 연결한다.
 SyntyStoryUpgrade.Skin(m.passenger,"Assets/Synty/PolygonCity/Prefabs/Characters/Character_Male_Hoodie.prefab","PlayerVenuePassenger",false,true);foreach(var r in m.passenger.GetComponentsInChildren<MeshRenderer>(true))r.enabled=false;
 EditorUtility.SetDirty(m);EditorUtility.SetDirty(chase);AssetDatabase.SaveAssets();Rebuild(m);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Validate();Preview();File.WriteAllText("Logs/Venue-escape-apply.txt","Saved original entrance return; street route "+total.ToString("F1")+"m; 3 x 4 pursuit posts; Synty walls and floors; hoodie passenger.");
 }
 static void Rebuild(VenueFinale m){var surface=m.interior.GetComponent<NavMeshSurface>();surface.BuildNavMesh();var saved=AssetDatabase.LoadAssetAtPath<NavMeshData>("Assets/Scripts/Mok/Art/VenueFinale/VenueNavigation.asset");var generated=surface.navMeshData;EditorUtility.CopySerialized(generated,saved);surface.RemoveData();surface.navMeshData=saved;surface.AddData();UnityEngine.Object.DestroyImmediate(generated);EditorUtility.SetDirty(saved);AssetDatabase.SaveAssets();}
 public static void Validate(){var m=Find();string s="Venue entry return and pursuit paths\n";void PathCheck(Vector3 a,Vector3 b,string label){var p=new NavMeshPath();bool ok=NavMesh.CalculatePath(a,b,NavMesh.AllAreas,p)&&p.status==NavMeshPathStatus.PathComplete;s+=(ok?"PASS ":"FAIL ")+label+"\n";}
 var route=new[]{m.observeStand}.Concat(m.serviceRoute).ToArray();for(int n=1;n<route.Length;n++)PathCheck(route[n-1].position,route[n].position,route[n].name);route=new[]{m.entry}.Concat(m.alleyRoute).Concat(new[]{m.carStand}).ToArray();for(int n=1;n<route.Length;n++)PathCheck(route[n-1].position,route[n].position,route[n].name);foreach(var t in m.streetPursuit.firstWave.Concat(m.streetPursuit.secondWave).Concat(m.streetPursuit.thirdWave))PathCheck(t.position,m.carStand.position,t.name);File.WriteAllText("Logs/Venue-escape-geometry.txt",s);if(s.Contains("FAIL"))throw new Exception(s);}
 static void Capture(Vector3 at,Vector3 look,string file){var go=new GameObject("Venue architecture preview");var cam=go.AddComponent<Camera>();var rt=new RenderTexture(1280,720,24);var old=RenderTexture.active;try{cam.transform.position=at;cam.transform.LookAt(look);cam.fieldOfView=65;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1280,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();File.WriteAllBytes("Logs/"+file+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{RenderTexture.active=old;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static void SignFix(){var m=Find();foreach(var t in m.interior.GetComponentsInChildren<TextMesh>(true)){if(t.text=="EXIT"){t.text="시설 통로";t.transform.Rotate(0,180,0,Space.Self);EditorUtility.SetDirty(t);}if(t.text.Contains("SERVICE")&&t.text.Contains("출구")){t.text="출입구는 접수실 방향";EditorUtility.SetDirty(t);}}
 var go=new GameObject("Original entrance exit label");go.transform.SetParent(m.interior.transform,false);go.transform.localPosition=new Vector3(-28,3.15f,-13.55f);go.transform.localRotation=Quaternion.Euler(0,180,0);var text=go.AddComponent<TextMesh>();text.text="행사장 입구  /  EXIT";text.font=AssetDatabase.LoadAssetAtPath<Font>("Assets/Fonts/BMJUA_ttf.ttf");text.fontSize=64;text.characterSize=.035f;text.anchor=TextAnchor.MiddleCenter;text.color=new Color(1,.8f,.5f);go.GetComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/VenueFinale/Venue depth lettering.mat");go.AddComponent<PrologueDepthText>();EditorSceneManager.MarkSceneDirty(m.gameObject.scene);EditorSceneManager.SaveScene(m.gameObject.scene);Preview();}
 public static void Preview(){var m=Find();var w=m.interior.transform;Capture(m.inside.position+Vector3.up*1.6f,w.TransformPoint(new Vector3(-28,1.5f,0)),"Venue-synty-reception");Capture(w.TransformPoint(new Vector3(-2,1.6f,-26)),w.TransformPoint(new Vector3(-9,1.5f,-26)),"Venue-sealed-door");VenueFinaleBuilder.Preview();}
 public static void Audit(){var m=Find();string s="entry="+m.entry.position+" streetArrival="+m.streetArrival.position+" turn="+m.escapeTurn.position+" car="+m.carStand.position+" interiorExit="+m.interior.transform.InverseTransformPoint(m.interiorExit.position)+"\n";var path=new NavMeshPath();NavMesh.CalculatePath(m.entry.position,m.carStand.position,NavMesh.AllAreas,path);s+="STREET PATH "+path.status+" "+string.Join(";",path.corners.Select(p=>p.ToString()))+"\n";
 foreach(var r in m.interior.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name.ToLower().Contains("wall")||r.name.ToLower().Contains("door")||r.name.ToLower().Contains("floor")||r.name.ToLower().Contains("ceiling")))s+=r.name+" active="+r.enabled+" center="+m.interior.transform.InverseTransformPoint(r.bounds.center)+" size="+r.bounds.size+"\n";
 foreach(string n in new[]{"SM_Env_Wall_Interior_01","SM_Env_Wall_Interior_Ground_01","SM_Env_Wall_Interior_Door_01","SM_Env_Floor_01","SM_Env_Floor_02"}){var a=AssetDatabase.LoadAssetAtPath<GameObject>(Env+n+".prefab");var g=UnityEngine.Object.Instantiate(a);s+=n+" "+BoundsOf(g)+" mats="+string.Join(";",g.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct().Select(mat=>AssetDatabase.GetAssetPath(mat)+" shader="+mat.shader.name))+"\n";UnityEngine.Object.DestroyImmediate(g);}
 File.WriteAllText("Logs/Venue-escape-audit.txt",s);
 }
}
